// --- IndexedDB Wrapper for State ---
const DB_NAME = 'AKTScoringDB';
const STORE_NAME = 'appState';
const STATE_ID = 'mainState';

function initDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onerror = (e) => reject(e);
    request.onsuccess = (e) => resolve(e.target.result);
    request.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
  });
}

let stateSaveQueue = Promise.resolve();
let stateSaveTimer = null;

function saveStateToIDB() {
  // 呼び出し時点の状態をスナップショット化し、保存順を保証する。
  // トランザクション完了まで待つことで、採点直後の画面移動・再読込で値が欠落するのを防ぐ。
  const snapshot = JSON.parse(JSON.stringify(state));
  stateSaveQueue = stateSaveQueue.catch(() => {}).then(async () => {
    try {
      const db = await initDB();
      await new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        tx.oncomplete = () => { db.close(); resolve(); };
        tx.onerror = () => { db.close(); reject(tx.error); };
        tx.onabort = () => { db.close(); reject(tx.error || new Error('IDB transaction aborted')); };
        tx.objectStore(STORE_NAME).put(snapshot, STATE_ID);
      });
    } catch(e) {
      console.error("IDB save error", e);
    }
  });
  return stateSaveQueue;
}

function scheduleStateSave() {
  clearTimeout(stateSaveTimer);
  stateSaveTimer = setTimeout(() => saveStateToIDB(), 250);
}

async function loadStateFromIDB() {
  try {
    const db = await initDB();
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const saved = await new Promise((resolve) => {
      const req = store.get(STATE_ID);
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
    });
    if (saved) {
      Object.assign(state, saved);
      return saved;
    }
  } catch(e) {
    console.error("IDB load error", e);
  }
  return null;
}

function getTodayIsoDate() {
  const now = new Date();
  const local = new Date(now.getTime() - now.getTimezoneOffset() * 60000);
  return local.toISOString().split('T')[0];
}

