// Core Scoring Logic
async function startScoringSequence() {
  if (appStores.length === 0) {
    alert("巡回する店舗が設定されていません。管理者設定から店舗を追加してください。");
    return;
  }
  if (!dateSelect.value) {
    alert("審査日を選択してください。");
    return;
  }
  if (!evaluatorInput.value.trim()) {
    alert("審査員名を入力してください。");
    return;
  }

  state.date = dateSelect.value;
  state.edition = editionSelect.value;
  state.evaluator = evaluatorInput.value.trim();
  state.routeIndex = 0;
  state.currentCategory = '';
  state.reviewStatus = 'in_progress';
  state.startedAt = new Date().toISOString();
  state.completedAt = '';
  state.answers = {};
  
  appStores.forEach(s => { 
    state.answers[s] = {
      hallStoreComment: '',
      backyardStoreComment: '',
      storeComment: '',
      staffName: '',
      staffPosition: '',
      staffReason: ''
    }; 
  });
  
  await saveStateToIDB();

  loadStoreScoring();
  switchScreen('scoring');
  scrollPageToTop();
}

function getFilteredChecklist() {
  const routeStores = getRouteStores();
  const storeName = routeStores[state.routeIndex];
  
  if (storeName === '本部' || storeName.includes('本部')) {
    if (state.edition === 'hall') return [];
    return appChecklist.filter(cat => cat.edition === 'hq');
  }

  if (state.edition === 'all') {
    return appChecklist.filter(cat => cat.edition !== 'hq');
  }
  
  return appChecklist.filter(cat => (cat.edition === 'both' || cat.edition === state.edition || !cat.edition) && cat.edition !== 'hq');
}

function isHQStoreName(storeName) {
  return storeName === '本部' || String(storeName || '').includes('本部');
}

function getStoreCommentForEdition(storeAnswers, edition) {
  if (edition === 'hall') return getHallSummaryComment(storeAnswers);
  if (edition === 'backyard') return getBackyardSummaryComment(storeAnswers);
  return firstNonEmptySummaryValue([storeAnswers?.storeComment]);
}

function firstNonEmptySummaryValue(candidates) {
  for (const value of candidates || []) {
    if (value !== undefined && value !== null && String(value).trim()) return String(value);
  }
  return '';
}

function getHallSummaryComment(storeAnswers) {
  if (!storeAnswers) return '';
  return firstNonEmptySummaryValue([
    storeAnswers.hallStoreComment,
    storeAnswers.hallSummary?.comment,
    storeAnswers.__hall_summary__?.comment,
    storeAnswers.storeComment
  ]);
}

function getBackyardSummaryComment(storeAnswers) {
  if (!storeAnswers) return '';
  return firstNonEmptySummaryValue([
    storeAnswers.backyardStoreComment,
    storeAnswers.backyardSummary?.comment,
    storeAnswers.__backyard_summary__?.comment,
    storeAnswers.storeComment
  ]);
}

function persistStoreSummaryComment(storeAnswers, edition, value) {
  if (!storeAnswers) return;
  const text = String(value ?? '');
  if (edition === 'hall') {
    storeAnswers.hallStoreComment = text;
    storeAnswers.hallSummary = { ...(storeAnswers.hallSummary || {}), comment: text };
    storeAnswers.__hall_summary__ = { ...(storeAnswers.__hall_summary__ || {}), comment: text };
  } else if (edition === 'backyard') {
    storeAnswers.backyardStoreComment = text;
    storeAnswers.backyardSummary = { ...(storeAnswers.backyardSummary || {}), comment: text };
    storeAnswers.__backyard_summary__ = { ...(storeAnswers.__backyard_summary__ || {}), comment: text };
  }
}

function getHQSummaryComment(storeAnswers) {
  if (!storeAnswers) return '';
  const candidates = [
    storeAnswers.hqStoreComment,
    storeAnswers.storeComment,
    storeAnswers.summaryComment,
    storeAnswers.hqSummary?.comment,
    storeAnswers.__hq_summary__?.comment
  ];
  for (const value of candidates) {
    if (value !== undefined && value !== null && String(value).trim()) return String(value);
  }
  return '';
}

function persistHQSummaryComment(storeAnswers, value) {
  if (!storeAnswers) return;
  const text = String(value ?? '');
  // 旧GAS・旧クライアントとの互換性を保つため、従来キーとオブジェクト型キーの両方へ保持する。
  storeAnswers.hqStoreComment = text;
  storeAnswers.storeComment = text;
  storeAnswers.summaryComment = text;
  storeAnswers.hqSummary = { ...(storeAnswers.hqSummary || {}), comment: text };
  storeAnswers.__hq_summary__ = { ...(storeAnswers.__hq_summary__ || {}), comment: text };
}

function saveVisibleStoreComments(storeAnswers) {
  const routeStores = getRouteStores();
  const storeName = routeStores[state.routeIndex];
  if (!storeAnswers || isHQStoreName(storeName)) {
    if (storeAnswers) persistHQSummaryComment(storeAnswers, storeCommentInput.value);
    return;
  }

  if (state.edition === 'hall' || state.edition === 'all') {
    persistStoreSummaryComment(storeAnswers, 'hall', storeCommentInput.value);
  }
  if (state.edition === 'backyard' || state.edition === 'all') {
    persistStoreSummaryComment(storeAnswers, 'backyard', backyardStoreCommentInput.value);
  }
}

// ホール端末とバックヤード端末は同じ店舗レコードへ順番に保存されるため、
// 反対側の未入力キー（空文字）まで送ると、後から送った端末が既存総評を消してしまう。
// 各端末からは自分の編に属する総評・担当者情報だけを送信する。
function buildEditionScopedCloudAnswers(storeName, storeAnswers, edition) {
  const scopedAnswers = { ...(storeAnswers || {}) };
  if (isHQStoreName(storeName)) return scopedAnswers;

  const legacyComment = String(scopedAnswers.storeComment ?? '');
  if (edition === 'hall') {
    const hallComment = getHallSummaryComment(scopedAnswers) || legacyComment;
    if (hallComment) persistStoreSummaryComment(scopedAnswers, 'hall', hallComment);
    delete scopedAnswers.backyardStoreComment;
    delete scopedAnswers.backyardSummary;
    delete scopedAnswers.__backyard_summary__;
    delete scopedAnswers.backyardEvaluator;
  } else if (edition === 'backyard') {
    const backyardComment = getBackyardSummaryComment(scopedAnswers) || legacyComment;
    if (backyardComment) persistStoreSummaryComment(scopedAnswers, 'backyard', backyardComment);
    delete scopedAnswers.hallStoreComment;
    delete scopedAnswers.hallSummary;
    delete scopedAnswers.__hall_summary__;
    delete scopedAnswers.hallEvaluator;
    // 輝いていたスタッフ欄はホール編のみの入力項目。
    delete scopedAnswers.staffName;
    delete scopedAnswers.staffPosition;
    delete scopedAnswers.staffReason;
  }

  // 店舗の旧共通キーは編別キーへ移行済み。共通キーを送ると再び上書き原因になる。
  if (edition === 'hall' || edition === 'backyard') delete scopedAnswers.storeComment;
  return scopedAnswers;
}

function loadStoreScoring() {
  const routeStores = getRouteStores();
  const storeName = routeStores[state.routeIndex];
  
  currentStoreHeader.textContent = `現在: ${storeName}`;
  storeProgressText.textContent = `${storeName} の審査 (${state.routeIndex + 1} / ${routeStores.length} 店舗)`;
  
  if (state.routeIndex < routeStores.length - 1) {
    btnNextStore.classList.remove('hidden');
    btnFinish.classList.add('hidden');
  } else {
    btnNextStore.classList.add('hidden');
    btnFinish.classList.remove('hidden');
  }

  if (state.routeIndex > 0) {
    btnPrevStore.classList.remove('hidden');
  } else {
    btnPrevStore.classList.add('hidden');
  }

  let storeAnswers = state.answers[storeName];
  if (!storeAnswers) {
    storeAnswers = { hallStoreComment: '', backyardStoreComment: '', storeComment: '', staffName: '', staffPosition: '', staffReason: '' };
    state.answers[storeName] = storeAnswers;
  }
  const isHQStore = isHQStoreName(storeName);
  if (hallStoreCommentLabel?.childNodes[0]) {
    hallStoreCommentLabel.childNodes[0].nodeValue = isHQStore ? '本部 総評コメント ' : 'ホール編 総評コメント ';
  }
  hallSummaryRequired?.classList.remove('hidden');
  storeCommentInput.classList.remove('input-error');
  backyardStoreCommentInput.classList.remove('input-error');
  storeCommentInput.value = isHQStore
    ? getHQSummaryComment(storeAnswers)
    : getStoreCommentForEdition(storeAnswers, 'hall');
  backyardStoreCommentInput.value = getStoreCommentForEdition(storeAnswers, 'backyard');
  hallStoreCommentSection.classList.toggle('hidden', !isHQStore && state.edition === 'backyard');
  backyardStoreCommentSection.classList.toggle('hidden', isHQStore || state.edition === 'hall');
  staffNameInput.value = storeAnswers.staffName || '';
  staffPositionInput.value = storeAnswers.staffPosition || '';
  staffReasonInput.value = storeAnswers.staffReason || '';

  if (state.edition === 'hall') {
    staffSummarySection.classList.remove('hidden');
  } else {
    staffSummarySection.classList.add('hidden');
  }

  renderCategories();
  const filteredChecklist = getFilteredChecklist();
  if (filteredChecklist.length > 0) {
    selectCategory(filteredChecklist[0].category);
  } else {
    questionsContainer.innerHTML = '<p class="text-secondary text-center">この編に該当する設問がありません。</p>';
  }
  updateTotalScore();
}

async function handleStorePrevious() {
  if (state.routeIndex > 0) {
    // 戻る前に現在の入力内容を保存する
    const routeStores = getRouteStores();
    const storeName = routeStores[state.routeIndex];
    const storeAnswers = state.answers[storeName];
    
    saveVisibleStoreComments(storeAnswers);
    storeAnswers.staffName = staffNameInput.value;
    storeAnswers.staffPosition = staffPositionInput.value;
    storeAnswers.staffReason = staffReasonInput.value;
    
    state.routeIndex--;
    state.reviewStatus = 'in_progress';
    await saveStateToIDB();

    loadStoreScoring();
    window.scrollTo(0, 0); // 一番上に戻す
  }
}

async function handleStoreCompletion(isFinal) {
  const routeStores = getRouteStores();
  const storeName = routeStores[state.routeIndex];
  const storeAnswers = state.answers[storeName];
  
  saveVisibleStoreComments(storeAnswers);
  storeAnswers.staffName = staffNameInput.value;
  storeAnswers.staffPosition = staffPositionInput.value;
  storeAnswers.staffReason = staffReasonInput.value;

  const filteredChecklist = getFilteredChecklist();
  
  const missingScores = [];
  const missingRequiredComments = [];
  const missingRequiredFields = [];
  filteredChecklist.forEach(cat => {
    cat.items.forEach(item => {
      const answer = storeAnswers[item.id] || {};
      if (answer.score === undefined) missingScores.push({ category: cat.category, item, field: 'score' });
      if (requiresCommentForScore(item, answer.score) && !String(answer.comment || '').trim()) {
        missingRequiredComments.push({ category: cat.category, item, field: 'comment' });
      }
      if (item.hasTempHumidity) {
        if (!String(answer.temperature ?? '').trim()) {
          missingRequiredFields.push({ category: cat.category, item, field: 'temperature' });
        }
        if (!String(answer.humidity ?? '').trim()) {
          missingRequiredFields.push({ category: cat.category, item, field: 'humidity' });
        }
      }
    });
  });

  if (missingRequiredFields.length > 0) {
    const missingLabels = [...new Set(missingRequiredFields.map(issue => issue.field === 'temperature' ? '温度' : '湿度'))];
    alert(`${missingLabels.join('・')}が未入力です。入力が必要な項目へ移動します。`);
    await saveStateToIDB();
    jumpToChecklistIssue(missingRequiredFields[0]);
    return;
  }

  if (missingRequiredComments.length > 0) {
    alert(`必須コメントの未入力が ${missingRequiredComments.length} 個あります。最初の該当項目へ移動します。`);
    await saveStateToIDB();
    jumpToChecklistIssue(missingRequiredComments[0]);
    return;
  }

  const requiredSummary = [];
  if (isHQStoreName(storeName)) {
    if (!getHQSummaryComment(storeAnswers).trim()) {
      requiredSummary.push({ input: storeCommentInput, label: '本部' });
    }
  } else {
    if ((state.edition === 'hall' || state.edition === 'all') && !getHallSummaryComment(storeAnswers).trim()) {
      requiredSummary.push({ input: storeCommentInput, label: 'ホール編' });
    }
    if ((state.edition === 'backyard' || state.edition === 'all') && !getBackyardSummaryComment(storeAnswers).trim()) {
      requiredSummary.push({ input: backyardStoreCommentInput, label: 'バックヤード編' });
    }
  }
  if (requiredSummary.length > 0) {
    alert(`${requiredSummary.map(x => x.label).join('・')}の総評コメントを入力してください。`);
    const target = requiredSummary[0].input;
    target.classList.add('input-error');
    target.scrollIntoView({ behavior: 'smooth', block: 'center' });
    target.focus({ preventScroll: true });
    await saveStateToIDB();
    return;
  }

  if (missingScores.length > 0) {
    const proceed = confirm(`未回答の項目が ${missingScores.length} 個あります。\n\n未回答のまま次へ進みますか？\n\n「OK」: 未回答のまま進む\n「キャンセル」: 最初の未入力項目へ移動`);
    if (!proceed) {
      await saveStateToIDB();
      jumpToChecklistIssue(missingScores[0]);
      return;
    }
  }
  
  if (isFinal) {
    state.reviewStatus = 'completed';
    state.completedAt = new Date().toISOString();
    await saveStateToIDB();
    switchScreen('result');
  } else {
    state.routeIndex++;
    state.reviewStatus = 'in_progress';
    await saveStateToIDB();
    loadStoreScoring();
    window.scrollTo(0,0);
  }
}

function requiresCommentForScore(item, score) {
  // 指定された強化項目（5S・AI）は、選択点数に関係なくコメント必須。
  if (['q_special', 'q_special_ai'].includes(item.id)) return true;
  if (score === undefined || score === null) return false;

  // 通常項目は低評価時のみ必須。
  // 3/1/0等は「一部(1)・未実施(0)」、1/0項目は「出来ていない(0)」が対象。
  if (Number(score) === 0) return true;
  return item.points.length > 2 && Number(score) === 1;
}

function jumpToChecklistIssue(issue) {
  if (!issue) return;
  selectCategory(issue.category);
  requestAnimationFrame(() => {
    const card = questionsContainer.querySelector(`[data-question-id="${issue.item.id}"]`);
    if (!card) return;
    card.classList.add('needs-attention');
    card.scrollIntoView({ behavior: 'smooth', block: 'center' });
    if (issue.field === 'comment') {
      const commentInput = card.querySelector('.comment-input');
      commentInput?.classList.add('input-error');
      commentInput?.focus({ preventScroll: true });
    } else if (issue.field === 'temperature' || issue.field === 'humidity') {
      const requiredInput = card.querySelector(`[data-required-field="${issue.field}"]`);
      requiredInput?.classList.add('input-error');
      requiredInput?.focus({ preventScroll: true });
    }
    setTimeout(() => card.classList.remove('needs-attention'), 2600);
  });
}

function renderCategories() {
  categoryTabs.innerHTML = '';
  const filteredChecklist = getFilteredChecklist();
  filteredChecklist.forEach(cat => {
    const btn = document.createElement('button');
    btn.className = 'tab-btn';
    btn.textContent = cat.category;
    btn.addEventListener('click', () => selectCategory(cat.category, true));
    categoryTabs.appendChild(btn);
  });
}

function selectCategory(categoryName, scrollToTop = false) {
  state.currentCategory = categoryName;
  document.querySelectorAll('.tab-btn').forEach(btn => {
    if (btn.textContent === categoryName) {
      btn.classList.add('active');
      btn.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
    } else {
      btn.classList.remove('active');
    }
  });
  renderQuestions(categoryName);
  if (scrollToTop) {
    requestAnimationFrame(() => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }
}

function compressImage(file, callback) {
  const reader = new FileReader();
  reader.onload = function(e) {
    const img = new Image();
    img.onload = function() {
      const canvas = document.createElement('canvas');
      const MAX_WIDTH = 800;
      const MAX_HEIGHT = 800;
      let width = img.width;
      let height = img.height;

      if (width > height) {
        if (width > MAX_WIDTH) {
          height *= MAX_WIDTH / width;
          width = MAX_WIDTH;
        }
      } else {
        if (height > MAX_HEIGHT) {
          width *= MAX_HEIGHT / height;
          height = MAX_HEIGHT;
        }
      }

      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, width, height);
      
      const dataUrl = canvas.toDataURL('image/jpeg', 0.6);
      callback(dataUrl);
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function getAnswerPhotos(answer) {
  if (!answer) return [];
  if (Array.isArray(answer.photos)) return answer.photos.filter(Boolean);
  return answer.photo ? [answer.photo] : [];
}

function compressImageAsync(file) {
  return new Promise(resolve => compressImage(file, resolve));
}

function renderQuestions(categoryName) {
  questionsContainer.innerHTML = '';
  const categoryData = appChecklist.find(c => c.category === categoryName);
  if (!categoryData) return;

  const routeStores = getRouteStores();
  const storeName = routeStores[state.routeIndex];
  const storeAnswers = state.answers[storeName];

  categoryData.items.forEach((item, index) => {
    const qDiv = document.createElement('div');
    qDiv.className = 'question-card';
    qDiv.dataset.questionId = item.id;
    if (storeAnswers[item.id] && storeAnswers[item.id].score !== undefined) qDiv.classList.add('answered');
    if (item.isPriority) qDiv.classList.add('priority-item');

    // Title
    const qTitle = document.createElement('div');
    qTitle.className = 'question-text';
    const priorityBadge = item.isPriority ? '<span class="priority-badge">強化項目</span> ' : '';
    qTitle.innerHTML = `${priorityBadge}${index + 1}. ${item.text}`;
    qDiv.appendChild(qTitle);

    // Score Buttons
    const btnContainer = document.createElement('div');
    btnContainer.className = 'score-buttons';
    
    const getLabel = (pts) => {
      if(item.points.length === 2 && item.points.includes(1) && item.points.includes(0)) {
        if(pts === 1) return "出来ている(1)";
        if(pts === 0) return "出来ていない(0)";
      }
      if(pts === 10) return "◎(10)";
      if(pts === 8) return "〇(8)";
      if(pts === 5) return "良好(5)";
      if(pts === 4) return "△(4)";
      if(pts === 3) return "良好(3)";
      if(pts === 1) return "一部(1)";
      if(pts === 0) return "未実施(0)";
      return `${pts}点`;
    };

    let updateCommentRequirement = () => {};
    item.points.forEach((pts, btnIndex) => {
      const btn = document.createElement('button');
      btn.className = 'score-btn';
      btn.type = 'button';
      
      if (btnIndex === 0) btn.classList.add('score-high');
      else if (btnIndex === item.points.length - 1) btn.classList.add('score-zero');
      else btn.classList.add('score-mid');

      btn.dataset.value = pts;
      btn.textContent = getLabel(pts);
      
      if (storeAnswers[item.id] && storeAnswers[item.id].score === pts) {
        btn.classList.add('selected');
        btn.setAttribute('aria-pressed', 'true');
      } else {
        btn.setAttribute('aria-pressed', 'false');
      }

      btn.addEventListener('click', async () => {
        Array.from(btnContainer.children).forEach(b => {
          b.classList.remove('selected');
          b.setAttribute('aria-pressed', 'false');
        });
        btn.classList.add('selected');
        btn.setAttribute('aria-pressed', 'true');
        
        if (!storeAnswers[item.id]) storeAnswers[item.id] = {};
        storeAnswers[item.id].score = pts;
        updateCommentRequirement(pts);
        
        qDiv.classList.add('answered');
        updateTotalScore();
        await saveStateToIDB();
      });

      btnContainer.appendChild(btn);
    });
    qDiv.appendChild(btnContainer);

    // Comment Input（強化項目は常時必須、通常項目は低評価時のみ必須）
    const commentLabel = document.createElement('div');
    commentLabel.className = 'question-comment-label';
    commentLabel.textContent = 'コメント ';
    const requiredMark = document.createElement('span');
    requiredMark.className = 'required-mark';
    requiredMark.textContent = '必須';
    commentLabel.appendChild(requiredMark);
    qDiv.appendChild(commentLabel);

    const commentInput = document.createElement('textarea');
    commentInput.className = 'comment-input';
    if (storeAnswers[item.id] && storeAnswers[item.id].comment) {
      commentInput.value = storeAnswers[item.id].comment;
    }
    updateCommentRequirement = (score) => {
      const required = requiresCommentForScore(item, score);
      requiredMark.classList.toggle('hidden', !required);
      commentInput.classList.toggle('required-input', required);
      commentInput.required = required;
      commentInput.setAttribute('aria-required', required ? 'true' : 'false');
      commentInput.placeholder = required ? 'コメントを入力してください（必須）' : '改善点・コメント等...';
      if (!required) commentInput.classList.remove('input-error');
    };
    updateCommentRequirement(storeAnswers[item.id]?.score);
    commentInput.addEventListener('input', (e) => {
      if (!storeAnswers[item.id]) storeAnswers[item.id] = {};
      storeAnswers[item.id].comment = e.target.value;
      if (String(e.target.value || '').trim()) commentInput.classList.remove('input-error');
      scheduleStateSave();
    });
    qDiv.appendChild(commentInput);

    // Photo Upload UI
    const photoContainer = document.createElement('div');
    photoContainer.className = 'photo-upload-container';
    
    const photoLabel = document.createElement('label');
    photoLabel.innerHTML = '📷 写真を追加（複数可）';
    photoLabel.className = 'btn btn-secondary btn-small';
    photoLabel.style = 'cursor: pointer; display: inline-block;';
    
    const photoBtn = document.createElement('input');
    photoBtn.type = 'file';
    photoBtn.accept = 'image/*';
    photoBtn.capture = 'environment';
    photoBtn.multiple = true;
    photoBtn.style.display = 'none';
    photoLabel.appendChild(photoBtn);
    
    const previewDiv = document.createElement('div');
    previewDiv.className = 'photo-preview-list';

    const renderPreviews = () => {
      previewDiv.innerHTML = '';
      const photos = getAnswerPhotos(storeAnswers[item.id]);
      photos.forEach((base64Str, photoIndex) => {
        const itemDiv = document.createElement('div');
        itemDiv.className = 'photo-preview-item';
        const img = document.createElement('img');
        img.src = base64Str;

        const removeBtn = document.createElement('button');
        removeBtn.type = 'button';
        removeBtn.className = 'photo-remove-btn';
        removeBtn.setAttribute('aria-label', `${photoIndex + 1}枚目の写真を削除`);
        removeBtn.innerHTML = '×';
        removeBtn.onclick = async () => {
          const nextPhotos = getAnswerPhotos(storeAnswers[item.id]).filter((_, i) => i !== photoIndex);
          storeAnswers[item.id].photos = nextPhotos;
          delete storeAnswers[item.id].photo;
          renderPreviews();
          await saveStateToIDB();
        };

        itemDiv.appendChild(img);
        itemDiv.appendChild(removeBtn);
        previewDiv.appendChild(itemDiv);
      });
    };

    renderPreviews();

    photoBtn.addEventListener('change', async (e) => {
      const files = Array.from(e.target.files || []);
      if (files.length > 0) {
        photoLabel.innerHTML = '処理中...';
        if (!storeAnswers[item.id]) storeAnswers[item.id] = {};
        const addedPhotos = await Promise.all(files.map(compressImageAsync));
        const nextPhotos = getAnswerPhotos(storeAnswers[item.id]).concat(addedPhotos);
        storeAnswers[item.id].photos = nextPhotos;
        delete storeAnswers[item.id].photo;
        renderPreviews();
        await saveStateToIDB();
        photoBtn.value = '';
        photoLabel.innerHTML = '📷 写真を追加（複数可）';
        photoLabel.appendChild(photoBtn);
      }
    });

    photoContainer.appendChild(photoLabel);
    photoContainer.appendChild(previewDiv);
    qDiv.appendChild(photoContainer);

    // Temp/Humidity Inputs (if flagged)
    if (item.hasTempHumidity) {
      const metricDiv = document.createElement('div');
      metricDiv.className = 'required-metrics';

      const metricLabel = document.createElement('div');
      metricLabel.className = 'required-metrics-label';
      metricLabel.innerHTML = '温度・湿度 <span class="required-mark">必須</span>　※両方入力してください';
      metricDiv.appendChild(metricLabel);
      
      const tInput = document.createElement('input');
      tInput.type = 'number';
      tInput.placeholder = '温度（℃）必須';
      tInput.className = 'required-field';
      tInput.dataset.requiredField = 'temperature';
      tInput.required = true;
      tInput.setAttribute('aria-label', '温度（必須）');
      if (storeAnswers[item.id] && storeAnswers[item.id].temperature !== undefined) tInput.value = storeAnswers[item.id].temperature;
      tInput.addEventListener('input', (e) => {
        if (!storeAnswers[item.id]) storeAnswers[item.id] = {};
        storeAnswers[item.id].temperature = e.target.value;
        if (String(e.target.value || '').trim()) tInput.classList.remove('input-error');
        scheduleStateSave();
      });

      const hInput = document.createElement('input');
      hInput.type = 'number';
      hInput.placeholder = '湿度（%）必須';
      hInput.className = 'required-field';
      hInput.dataset.requiredField = 'humidity';
      hInput.required = true;
      hInput.setAttribute('aria-label', '湿度（必須）');
      if (storeAnswers[item.id] && storeAnswers[item.id].humidity !== undefined) hInput.value = storeAnswers[item.id].humidity;
      hInput.addEventListener('input', (e) => {
        if (!storeAnswers[item.id]) storeAnswers[item.id] = {};
        storeAnswers[item.id].humidity = e.target.value;
        if (String(e.target.value || '').trim()) hInput.classList.remove('input-error');
        scheduleStateSave();
      });

      metricDiv.appendChild(tInput);
      metricDiv.appendChild(hInput);
      qDiv.appendChild(metricDiv);
    }

    questionsContainer.appendChild(qDiv);
  });
}

function updateTotalScore() {
  const routeStores = getRouteStores();
  const storeName = routeStores[state.routeIndex];
  const storeAnswers = state.answers[storeName] || {};
  let total = 0;
  for (const qId in storeAnswers) {
    if (storeAnswers[qId] && storeAnswers[qId].score !== undefined) {
      total += storeAnswers[qId].score;
    }
  }
  totalScoreDisplay.textContent = total;
  return total;
}

async function returnToScoringFromResult() {
  const routeStores = getRouteStores();
  if (routeStores.length === 0) return;
  state.routeIndex = Math.max(0, routeStores.length - 1);
  state.reviewStatus = 'in_progress';
  state.completedAt = '';
  await saveStateToIDB();
  loadStoreScoring();
  switchScreen('scoring');
  scrollPageToTop();
}

async function resetApp() {
  const confirmReset = confirm("現在の入力データはすべて失われます。トップに戻りますか？");
  if (!confirmReset) return;

  setIdleState();
  dateSelect.value = getTodayIsoDate();
  editionSelect.value = 'all';
  evaluatorInput.value = '';
  reviewerPasswordInput.value = '';
  renderRoutePreview();
  await saveStateToIDB();
  switchScreen('setup');
}

async function sendDataToCloud() {
  btnSendData.disabled = true;
  btnSendData.textContent = '送信中...';
  
  try {
    let sentCount = 0;
    for (const storeName of appStores) {
      const storeAnswers = state.answers[storeName];
      if (!storeAnswers) continue;
      
      // 点数が入力されているかチェック
      let hasScore = Object.keys(storeAnswers).some(key => storeAnswers[key] && typeof storeAnswers[key] === 'object' && storeAnswers[key].score !== undefined);
      const hqSummaryComment = isHQStoreName(storeName) ? getHQSummaryComment(storeAnswers) : '';
      const hallSummaryComment = isHQStoreName(storeName) ? '' : getHallSummaryComment(storeAnswers);
      const backyardSummaryComment = isHQStoreName(storeName) ? '' : getBackyardSummaryComment(storeAnswers);
      if (!hasScore && !hqSummaryComment && !hallSummaryComment && !backyardSummaryComment && !storeAnswers.staffName) continue;

      // GASのload応答はanswersだけを返すため、審査員名もanswers内へ編別に保持する。
      if (isHQStoreName(storeName)) {
        persistHQSummaryComment(storeAnswers, hqSummaryComment);
        storeAnswers.hqEvaluator = state.evaluator || '';
      } else if (state.edition === 'hall') {
        storeAnswers.hallEvaluator = state.evaluator || '';
      } else if (state.edition === 'backyard') {
        storeAnswers.backyardEvaluator = state.evaluator || '';
      } else {
        storeAnswers.hallEvaluator = state.evaluator || '';
        storeAnswers.backyardEvaluator = state.evaluator || '';
      }
      
      const payload = {
        action: "save",
        date: state.date,
        edition: state.edition,
        evaluator: state.evaluator,
        storeName: storeName,
        answers: buildEditionScopedCloudAnswers(storeName, storeAnswers, state.edition)
      };

      console.log(`[送信] ${storeName} へ送信するデータ:`, payload);

      const res = await fetch(GAS_URL, {
        method: "POST",
        headers: { "Content-Type": "text/plain" },
        body: JSON.stringify(payload)
      });
      const resJson = await res.json().catch(() => null);
      console.log(`[送信] ${storeName} のGASレスポンス:`, resJson);
      if (!res.ok || !resJson || resJson.status !== 'success') {
        const detail = resJson && (resJson.message || resJson.error);
        throw new Error(`${storeName}のクラウド保存が確認できませんでした${detail ? `: ${detail}` : ''}`);
      }
      sentCount++;
    }
    
    if (sentCount === 0) {
      alert("送信する採点データがありませんでした。");
      btnSendData.textContent = '採点データを本部へ送信';
    } else {
      alert(`${sentCount}店舗のデータを本部へ送信しました！`);
      btnSendData.textContent = '再送信する';
    }
  } catch (err) {
    console.error(err);
    alert("送信に失敗しました。電波の良いところで再度お試しください。\n\nエラー: " + err.message);
    btnSendData.textContent = '採点データを本部へ送信';
  } finally {
    // 成功・失敗・例外 どのパスを通っても必ずボタンを有効化する
    btnSendData.disabled = false;
  }
}

async function fetchAndDownloadExcel() {
  if (appStores.length === 0) {
    alert("巡回する店舗が設定されていません。管理者設定から店舗を追加してください。");
    return;
  }
  if (!dateSelect.value) {
    alert("取得したい審査日を選択してください。");
    return;
  }
  
  btnFetchAndDownload.disabled = true;
  btnFetchAndDownload.textContent = 'クラウドからデータ取得中...';
  
  try {
    const payload = {
      action: "load",
      date: dateSelect.value
    };
    
    const res = await fetch(GAS_URL, {
      method: "POST",
      headers: { "Content-Type": "text/plain" },
      body: JSON.stringify(payload)
    });
    
    const data = await res.json();
    console.log("[クラウド取得結果] raw data:", data);

    if (data.status === "success" && data.answers) {
      // 取得したデータを現在の state にマージする
      state.date = dateSelect.value;

      // デバッグ用：店舗ごとに「クラウドから何件の回答（点数）が返ってきたか」を可視化する
      const debugLines = [];
      let totalCloudScores = 0;
      for (const storeName of appStores) {
        const cloudAns = data.answers[storeName];
        if (!cloudAns) {
          debugLines.push(`${storeName}: クラウドにデータ無し`);
          continue;
        }
        const scoredCount = Object.keys(cloudAns).filter(
          k => cloudAns[k] && typeof cloudAns[k] === 'object' && cloudAns[k].score !== undefined
        ).length;
        totalCloudScores += scoredCount;
        debugLines.push(`${storeName}: クラウドから${scoredCount}件の点数を取得`);
      }
      console.log("[クラウド取得結果] 店舗別件数:\n" + debugLines.join('\n'));

      if (totalCloudScores === 0) {
        alert(
          "⚠️ クラウドから採点点数が1件も取得できないため、Excel出力を中止しました。\n\n" +
          "【考えられる原因】\n" +
          "・選んだ審査日が、審査員が送信した日付と違う\n" +
          "・審査員が「採点データを本部へ送信」をまだ押していない\n" +
          "・送信時に通信またはGAS側の保存エラーが発生した\n\n" +
          "【店舗別の取得状況】\n" + debugLines.join('\n')
        );
        btnFetchAndDownload.textContent = 'クラウドデータを合体してExcel出力';
        btnFetchAndDownload.disabled = false;
        return;
      }

      for (const store in data.answers) {
        if (!state.answers[store]) state.answers[store] = {};
        const incomingAnswers = data.answers[store];
        if (isHQStoreName(store)) {
          const hqSummaryComment = getHQSummaryComment(incomingAnswers);
          if (hqSummaryComment) persistHQSummaryComment(incomingAnswers, hqSummaryComment);
        } else {
          const hallSummaryComment = getHallSummaryComment(incomingAnswers);
          const backyardSummaryComment = getBackyardSummaryComment(incomingAnswers);
          if (hallSummaryComment) persistStoreSummaryComment(incomingAnswers, 'hall', hallSummaryComment);
          if (backyardSummaryComment) persistStoreSummaryComment(incomingAnswers, 'backyard', backyardSummaryComment);
        }
        Object.assign(state.answers[store], incomingAnswers);
      }

      // 月別結果をクラウド履歴へ保存し、当年度4月からの履歴を取得する。
      // 履歴機能が通信エラーでも、従来のExcel出力自体は止めない。
      let monthlyHistoryMap = {};
      try {
        btnFetchAndDownload.textContent = '月別履歴を確認中...';
        await ensureBaselineHistorySeeded();

        const currentSnapshot = calculateMonthlySnapshotFromState(state.date);
        const autoSaveResult = await saveAutomaticMonthlySnapshot(currentSnapshot);
        monthlyHistoryMap = await loadFiscalHistoryForExport(state.date);

        // 今回のExcelでは選択した審査日の実績を必ず表示する。
        // ただし管理者が手動補正済みの場合は、手動補正値を優先する。
        const currentYm = currentSnapshot.yearMonth;
        const cloudCurrent = monthlyHistoryMap[currentYm];
        if (cloudCurrent?.manualOverride) {
          monthlyHistoryMap[currentYm] = cloudCurrent;
        } else {
          monthlyHistoryMap[currentYm] = currentSnapshot;
        }

        if (autoSaveResult.reason === 'manual-protected') {
          console.log('[月別履歴] 手動補正済みのため自動上書きをスキップしました');
        }
      } catch (historyErr) {
        console.warn('[月別履歴] 履歴処理でエラー。従来どおり今回月のみで出力します。', historyErr);
        const fallbackSnapshot = calculateMonthlySnapshotFromState(state.date);
        monthlyHistoryMap[fallbackSnapshot.yearMonth] = fallbackSnapshot;
      }
      
      // 合体したデータでExcel出力
      btnFetchAndDownload.textContent = 'Excel作成中...';
      await exportToExcelAll(btnFetchAndDownload, monthlyHistoryMap);
      btnFetchAndDownload.textContent = '出力完了！';
      btnFetchAndDownload.disabled = false;
    } else {
      throw new Error("Invalid response");
    }
  } catch (err) {
    console.error(err);
    alert("データの取得に失敗しました。");
    btnFetchAndDownload.textContent = 'クラウドデータを合体してExcel出力';
    btnFetchAndDownload.disabled = false;
  }
}

async function exportToExcelAll(btnElement, monthlyHistoryMap = {}) {
  if (!btnElement) btnElement = { textContent: '', disabled: false }; // ダミー
  
  if (appStores.length === 0) {
    alert("出力する店舗データがありません。");
    return;
  }
  
  btnElement.textContent = '出力中...';
  btnElement.disabled = true;

  try {
    const zip = new JSZip();
    const dateStr = state.date || new Date().toISOString().split('T')[0];
    const storeMatchCounts = []; // 全店舗のマッチ状況と書き込み列を保存

    // テンプレートファイルの読み込み
    // 1) 同フォルダの template.xlsx を優先利用
    // 2) 見つからない/公開先で取得不可なら、アプリ内蔵テンプレートへ自動フォールバック
    let templateBuffer;
    let usingEmbeddedTemplate = false;
    try {
      const response = await fetch('./template.xlsx');
      if (!response.ok) throw new Error('Template not found');
      templateBuffer = await response.arrayBuffer();
    } catch(e) {
      try {
        templateBuffer = base64ToArrayBuffer(EMBEDDED_TEMPLATE_XLSX_BASE64);
        usingEmbeddedTemplate = true;
        console.warn('template.xlsx の取得に失敗したため、内蔵テンプレートへ切り替えました。', e);
      } catch(embedErr) {
        console.error(embedErr);
        alert('template.xlsx の読み込みに失敗しました。');
        btnElement.textContent = 'Excel形式で一括出力';
        btnElement.disabled = false;
        return;
      }
    }

    // ── 全店舗スコアの事前計算（結果資料の全店表示・順位・色付けに使用）──
    const _hallCats    = appChecklist.filter(c => c.edition === 'hall');
    const _strengtheningIds = new Set(['q_special', 'q_special_ai']);
    const _backItems   = appChecklist.filter(c => c.edition === 'backyard').flatMap(c => c.items).filter(i => !_strengtheningIds.has(i.id));
    const _strengtheningItems = appChecklist.flatMap(c => c.items).filter(i => _strengtheningIds.has(i.id));
    const _hqCats      = appChecklist.filter(c => c.edition === 'hq');
    const _hallMax    = _hallCats.flatMap(c => c.items).reduce((s, i) => s + i.points[0], 0);
    const _backMax    = _backItems.reduce((s, i) => s + i.points[0], 0);
    const _fiveSMax   = _strengtheningItems.find(i => i.id === 'q_special')?.points[0] || 0;
    const _aiMax      = _strengtheningItems.find(i => i.id === 'q_special_ai')?.points[0] || 0;
    const _hqItemMax  = _hqCats.flatMap(c => c.items).length; // 各項目1点

    const allStoreCache = {}; // storeName → {total, hallRate, backRate, fiveSRate, aiRate, isHQ}
    for (const sName of appStores) {
      const ans = state.answers[sName] || {};
      const isHQ = sName === '本部' || sName.includes('本部');
      if (isHQ) {
        const hqScore = _hqCats.flatMap(c => c.items)
          .reduce((s, i) => s + ((ans[i.id]?.score ?? null) !== null ? ans[i.id].score : 0), 0);
        allStoreCache[sName] = {
          total: _hqItemMax > 0 ? Math.round(hqScore / _hqItemMax * 100) : 0,
          hallRate: null, backRate: null, fiveSRate: null, aiRate: null, isHQ: true
        };
      } else {
        const hallScore = _hallCats.flatMap(c => c.items)
          .reduce((s, i) => s + (ans[i.id]?.score !== undefined ? ans[i.id].score : 0), 0);
        const backScore = _backItems
          .reduce((s, i) => s + (ans[i.id]?.score !== undefined ? ans[i.id].score : 0), 0);
        const fiveSScore = ans['q_special']?.score ?? 0;
        const aiScore = ans['q_special_ai']?.score ?? 0;
        const backTotalMax   = _backMax + _fiveSMax + _aiMax;
        const backTotalScore = backScore + fiveSScore + aiScore;
        const hallP  = _hallMax > 0    ? Math.round(hallScore    / _hallMax    * 100) : 0;
        const backP  = backTotalMax > 0 ? Math.round(backTotalScore / backTotalMax * 100) : 0;
        allStoreCache[sName] = {
          total:       hallP + backP,
          hallRate:    _hallMax    > 0 ? hallScore    / _hallMax    : 0,
          backRate:    _backMax    > 0 ? backScore    / _backMax    : 0,
          fiveSRate:    _fiveSMax > 0 ? fiveSScore / _fiveSMax : 0,
          aiRate:       _aiMax > 0 ? aiScore / _aiMax : 0,
          isHQ: false
        };
      }
    }

    // 非HQ店舗のみ順位計算（同率考慮）
    const _ranked = Object.entries(allStoreCache)
      .filter(([, d]) => !d.isHQ)
      .map(([sName, d]) => ({ sName, total: d.total }))
      .sort((a, b) => b.total - a.total);

    const _maxScore = _ranked[0]?.total ?? 0;
    const _minScore = _ranked[_ranked.length - 1]?.total ?? 0;

    // 同点件数を集計
    const _scoreCounts = {};
    _ranked.forEach(({ total }) => {
      _scoreCounts[total] = (_scoreCounts[total] || 0) + 1;
    });

    // storeName → { rank: number, colorKey: 'red'|'gray'|'blue'|null }
    const _rankInfo = {};
    let _curRank = 0, _prevTotal = null;
    for (let i = 0; i < _ranked.length; i++) {
      const { sName, total } = _ranked[i];
      if (total !== _prevTotal) { _curRank = i + 1; _prevTotal = total; }

      let colorKey = null;
      if (total === _maxScore) {
        // 1位（同率1位含む）は赤
        colorKey = 'red';
      } else if (total === _minScore) {
        // 最下位（同率最下位含む）は灰色
        colorKey = 'gray';
      } else if ((_scoreCounts[total] || 0) >= 2) {
        // 1位・最下位以外の同率は青
        colorKey = 'blue';
      }

      _rankInfo[sName] = { rank: _curRank, colorKey };
    }

    // 結果資料 月列ヘルパー（4月=col2, 5月=col3, … 12月=col10, 1月=col11, … 3月=col13）
    const _getMonthCol = (dateStr) => {
      const d = new Date(dateStr + 'T00:00:00');
      const m = d.getMonth() + 1;
      return m >= 4 ? m - 2 : m + 10;
    };
    const _getMonthColFromYearMonth = (yearMonth) => {
      const m = Number(String(yearMonth || '').slice(5, 7));
      if (!Number.isFinite(m) || m < 1 || m > 12) return null;
      return m >= 4 ? m - 2 : m + 10;
    };
    const _monthCol = _getMonthCol(state.date);

    // 結果資料 店舗行検索ヘルパー
    // テンプレート側にふりがな・全角空白・「店」の有無などの表記差があっても一致させる
    const _normalizeStoreName = (value) => {
      if (value === null || value === undefined) return '';
      let text = value;
      if (typeof value === 'object' && value.richText) {
        text = value.richText.map(rt => rt.text || '').join('');
      }
      return String(text)
        .normalize('NFKC')
        .replace(/[\s　]/g, '')
        .replace(/店$/g, '')
        .toLowerCase();
    };

    const _findRow = (ws, minR, maxR, targetName) => {
      const target = _normalizeStoreName(targetName);
      let found = null;
      ws.eachRow((row, rn) => {
        if (found || rn < minR || rn > maxR) return;
        const cellName = _normalizeStoreName(row.getCell(1).value);
        if (!cellName) return;
        // 完全一致を優先し、テンプレートに読み仮名等が連結されている場合は前方一致で吸収
        if (cellName === target || cellName.startsWith(target) || target.startsWith(cellName)) {
          found = rn;
        }
      });
      return found;
    };

    // セル塗りつぶし適用ヘルパー（白文字・太字）
    const _applyColor = (cell, argb) => {
      cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb } };
      cell.font = { ...(cell.font || {}), color: { argb: 'FFFFFFFF' }, bold: true };
    };

    for (const storeName of appStores) {
      const workbook = new ExcelJS.Workbook();
      await workbook.xlsx.load(templateBuffer);

      // Excelが開いたとき、N70（5S得点集計）などの数式セルを
      // 強制的に再計算させる（これがないと書き込んだスコアが数式結果に反映されない）
      workbook.calcProperties = { fullCalcOnLoad: true };
      
      // シート名が店舗名を含むものがあればそれを使用、無ければ最初のシートを使用
      let targetWs = null;
      workbook.eachSheet((sheet) => {
        if (sheet.name.includes(storeName) || storeName.includes(sheet.name)) {
          targetWs = sheet;
        }
      });
      if (!targetWs) {
        targetWs = workbook.worksheets[0]; 
      }

      // 結果資料シートは出力に含めるため残し、それ以外の不要シートのみ削除する
      let kekkaWs = null;
      const sheetIdsToRemove = [];
      workbook.eachSheet((sheet) => {
        const isTarget = sheet.id === targetWs.id;
        const isKekka = sheet.name.includes('結果資料');
        if (!isTarget && !isKekka) {
          sheetIdsToRemove.push(sheet.id);
        }
        if (isKekka) kekkaWs = sheet;
      });
      sheetIdsToRemove.forEach(id => workbook.removeWorksheet(id));

      let ws = targetWs;
      ws.name = storeName.substring(0, 31); // 採点シートの名前を現在の店舗名にする

      const storeAnswers = state.answers[storeName] || {};
      const isHQStore = (storeName === '本部' || storeName.includes('本部'));
      // 本部用シートは本部編(hq)の項目のみ、店舗シートはhq以外の項目のみを対象にする
      // （「地域清掃活動は月1回～」のように、編をまたいで似た文言の設問が存在し、
      //   誤って違う編の項目とマッチしてしまうのを防ぐため）
      const targetChecklist = isHQStore
        ? appChecklist.filter(cat => cat.edition === 'hq')
        : appChecklist.filter(cat => cat.edition !== 'hq');

      // 日付を「○月○日（○）」「○○○○年○月○日（○）」形式に変換するヘルパー
      const formatDateJp = (dateStr, withYear) => {
        if (!dateStr) return '';
        const d = new Date(dateStr + 'T00:00:00');
        if (isNaN(d.getTime())) return dateStr;
        const week = ['日', '月', '火', '水', '木', '金', '土'][d.getDay()];
        return withYear
          ? `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日（${week}）`
          : `${d.getMonth() + 1}月${d.getDate()}日（${week}）`;
      };

      // 第○回は管理者設定の基準年月・基準回数から月ごとに+1する。
      const kaiNum = calcInspectionCount(state.date);
      const kaiText = kaiNum !== '' ? `第 ${kaiNum} 回　` : '';

      if (!isHQStore) {
        // ヘッダー：審査日／調査店舗／参加者
        ws.getCell('C3').value = formatDateJp(state.date, false);
        ws.getCell('I3').value = storeName;
        ws.getCell('K3').value = '';
        ws.getCell('N3').value = storeAnswers.hallEvaluator || storeAnswers.evaluatorName || state.evaluator || '';
        ws.getCell('P3').value = storeAnswers.backyardEvaluator || storeAnswers.evaluatorName || state.evaluator || '';
        // P1に日付シリアル値が残っているためクリアする
        ws.getCell('P1').value = '';
        // 第○回（最新2026年8月版の報告見出しはG83）
        if (kaiText) {
          ws.getCell('G1').value = kaiText;
          ws.getCell('G83').value = kaiText;
        }
      } else {
        // 本部用シート：回数／点検日／担当者
        ws.getCell('A1').value = `${kaiText}ＡＫＴ活動審査表`;
        ws.getCell('K1').value = `　点検日：${formatDateJp(state.date, true)}`;
        ws.getCell('C3').value = storeAnswers.hqEvaluator || storeAnswers.evaluatorName || state.evaluator || '';
      }

      let matchCount = 0; // マッチ件数カウント用
      const matchedRows = []; // 2パス書き込み用の配列

      // デフォルト（ヘッダーが見つからない場合の保険）
      const DEFAULT_SCORE_COL = 14;   // N列
      // 本部はコメント外枠の左端P列からU列まで結合する。
      // R列開始だとExcelJSの結合処理でQ列側にも不要な縦罫線が生じる。
      const DEFAULT_COMMENT_COL = isHQStore ? 16 : 15; // 店舗はO列、本部はP列

      // 記号や空白をすべて無視して純粋な文字だけで比較するための関数
      const normalize = (str) => {
        if (!str) return '';
        // Unicode正規化(NFKC)で全角英数字記号⇔半角、半角カナ⇔全角カナなどの
        // 表記ゆれをまとめて吸収する（例：％→%、ﾁｪｯｸ→チェック、１→1）
        let s = str.normalize('NFKC');
        s = s.replace(/[〜～]/g, '~');
        return s.replace(/[\s\n\r\t　・、。(),（）「」]/g, '').toLowerCase();
      };

      // テンプレートには「ホール編」「バックヤード編」「本部編」でスコア列・コメント列の
      // 実際の位置が異なる（特にコメント欄の位置が編によってズレている）ため、
      // 固定の列番号ではなく、シート内の「点数」「コメント欄」というラベルセルを
      // 実際にスキャンして、その時点で有効な列番号を行ごとに割り当てる。
      const rowScoreCol = {};
      const rowCommentCol = {};
      let lastScoreCol = DEFAULT_SCORE_COL;
      let lastCommentCol = DEFAULT_COMMENT_COL;

      ws.eachRow((row, rowNumber) => {
        row.eachCell((cell, colNumber) => {
          let cellText = '';
          if (cell.value && typeof cell.value === 'object' && cell.value.richText) {
            cellText = cell.value.richText.map(rt => rt.text).join('');
          } else if (typeof cell.value === 'string') {
            cellText = cell.value;
          }
          if (!cellText) return;

          // 結合セルの場合は左上(マスター)の列番号を採用する
          const masterCol = (cell.isMerged && cell.master) ? cell.master.col : colNumber;

          if (cellText.includes('点数')) {
            lastScoreCol = masterCol;
          }
          // 「コメント欄」という単独のラベルのみを対象とする
          // （「担当者総評コメント欄」のような別目的のラベルは除外）
          const strippedExact = cellText.trim().replace(/[（）()]/g, '');
          if (strippedExact === 'コメント欄') {
            lastCommentCol = masterCol;
          }
          // バックヤード編はヘッダーに「コメント欄」と明記されておらず、
          // 「理由を必ず明記して下さい」という注記がコメント欄の目印になっている
          if (cellText.includes('理由を必ず明記') || cellText.includes('コメント記入')) {
            lastCommentCol = masterCol;
          }
        });
        rowScoreCol[rowNumber] = lastScoreCol;
        rowCommentCol[rowNumber] = lastCommentCol;
      });

      // テンプレート内の各行を走査し、質問項目を探す
      ws.eachRow((row, rowNumber) => {
        let matchedItem = null;

        // 行内のセルをスキャンして質問文を探す
        // ※A〜C列はアイコン・カテゴリ名・No.が入っており、データ側の項目文に
        //   付いている【カテゴリ名】等の接頭辞と誤って部分一致することがあるため、
        //   実際の設問文が入っているD列以降だけを対象にする
        row.eachCell((cell, colNumber) => {
          if (matchedItem) return;
          if (colNumber < 4) return;
          // 結合セルのスレーブ（左上のマスター以外）はスキップ
          // （q26の空調行がD32:D33で結合されており、両行でマッチして2行書き込まれるのを防ぐ）
          if (cell.isMerged && cell.master.address !== cell.address) return;

          let cellText = '';
          if (cell.value && typeof cell.value === 'object' && cell.value.richText) {
            cellText = cell.value.richText.map(rt => rt.text).join('');
          } else if (typeof cell.value === 'string') {
            cellText = cell.value;
          }

          if (cellText) {
            const normCellText = normalize(cellText);
            if (normCellText.length > 5) { 
              for (const cat of targetChecklist) {
                const found = cat.items.find(i => {
                  const normItemText = normalize(i.text);
                  return normCellText.includes(normItemText) || normItemText.includes(normCellText);
                });
                if (found) {
                  matchedItem = found;
                  break;
                }
              }
            }
          }
        });
        
        if (matchedItem) {
          matchCount++;
          matchedRows.push({
            row: row,
            rowNumber: rowNumber,
            matchedItem: matchedItem,
            scoreCol: rowScoreCol[rowNumber] || DEFAULT_SCORE_COL,
            // 見出し文字の位置ではなく、罫線上の実開始列を使用する。
            // 店舗シートはO列、HQシートはP列。
            commentCol: DEFAULT_COMMENT_COL
          });
        }
      });

      // デバッグ用：マッチ件数を保持
      storeMatchCounts.push(`${storeName}: ${matchCount}件マッチ`);

      // 同一設問が複数行にマッチした場合（q26空調など行結合で2行マッチ）は最初の1件のみ使用
      const seenIds = new Set();
      const uniqueMatchedRows = matchedRows.filter(m => {
        if (seenIds.has(m.matchedItem.id)) return false;
        seenIds.add(m.matchedItem.id);
        return true;
      });

      const cloneBorderSide = (side) => side ? JSON.parse(JSON.stringify(side)) : undefined;
      const firstBorderSide = (cells, sideName) => {
        for (const cell of cells) {
          const side = cell.border?.[sideName];
          if (side?.style) return cloneBorderSide(side);
        }
        return undefined;
      };
      const mergeCellsWithOuterBorder = (startRow, startCol, endRow, endCol) => {
        const master = ws.getCell(startRow, startCol);
        if (master.isMerged) return master;

        const topCells = [];
        const bottomCells = [];
        const leftCells = [];
        const rightCells = [];
        for (let col = startCol; col <= endCol; col++) {
          topCells.push(ws.getCell(startRow, col));
          bottomCells.push(ws.getCell(endRow, col));
        }
        for (let row = startRow; row <= endRow; row++) {
          leftCells.push(ws.getCell(row, startCol));
          rightCells.push(ws.getCell(row, endCol));
        }
        const outerBorder = {
          left: firstBorderSide(leftCells, 'left'),
          right: firstBorderSide(rightCells, 'right'),
          top: firstBorderSide(topCells, 'top'),
          bottom: firstBorderSide(bottomCells, 'bottom')
        };

        ws.mergeCells(startRow, startCol, endRow, endCol);
        const mergedMaster = ws.getCell(startRow, startCol);

        // ExcelJSは結合セル全体で同じstyle参照を共有するため、単に右罫線を設定すると
        // 結合範囲内のセルにも縦線が複製される場合がある。各セルのstyleを切り離し、
        // 外周にだけ罫線を残す。
        for (let row = startRow; row <= endRow; row++) {
          for (let col = startCol; col <= endCol; col++) {
            const cell = ws.getCell(row, col);
            const border = { ...(cell.border || {}) };
            delete border.left;
            delete border.right;
            delete border.top;
            delete border.bottom;
            if (col === startCol && outerBorder.left) border.left = cloneBorderSide(outerBorder.left);
            if (col === endCol && outerBorder.right) border.right = cloneBorderSide(outerBorder.right);
            if (row === startRow && outerBorder.top) border.top = cloneBorderSide(outerBorder.top);
            if (row === endRow && outerBorder.bottom) border.bottom = cloneBorderSide(outerBorder.bottom);
            cell.style = {
              ...(cell.style || {}),
              border
            };
          }
        }
        return mergedMaster;
      };

      // 2パス目：行ごとに確定した列に点数とコメントを書き込む
      uniqueMatchedRows.forEach(m => {
        // コメント出力や結合によるExcel側の自動調整を防ぐため、
        // テンプレートで定義されている元の行高を最後に必ず復元する。
        const templateRowHeight = Number(m.row.height) || Number(ws.properties.defaultRowHeight) || 15;
        const ans = storeAnswers[m.matchedItem.id] || {};
        if (ans.score !== undefined) {
          m.row.getCell(m.scoreCol).value = ans.score;
        } else {
          m.row.getCell(m.scoreCol).value = "未入力";
        }

        // 見た目だけ広くなっていたコメント欄を、実際の右端まで結合する。
        // 店舗シートはT列、本部シートはU列が外枠の右端。
        const commentEndCol = isHQStore ? 21 : 20;
        if (m.commentCol <= commentEndCol) {
          mergeCellsWithOuterBorder(m.rowNumber, m.commentCol, m.rowNumber, commentEndCol);
        }
        if (ans.comment) {
          const commentCell = m.row.getCell(m.commentCol);
          commentCell.value = ans.comment;
          commentCell.alignment = {
            ...(commentCell.alignment || {}),
            horizontal: 'left',
            vertical: 'top',
            wrapText: false
          };
        }

        // 温度・湿度（空調項目）はスコア列の1つ右のセルに書き込む
        if (m.matchedItem.hasTempHumidity && (ans.temperature || ans.humidity)) {
          const tempCell = m.row.getCell(m.scoreCol + 1);
          const t = ans.temperature ? `${ans.temperature}℃` : '';
          const h = ans.humidity ? `${ans.humidity}%` : '';
          tempCell.value = `メイン温度：${t}　、　湿度：${h}`;
        }

        m.row.height = templateRowHeight;
      });

      const setSummaryComment = (address, text, rowNumber, mergeBounds) => {
        const templateRowHeights = [];
        if (mergeBounds) {
          const [startRow, , endRow] = mergeBounds;
          for (let row = startRow; row <= endRow; row++) {
            templateRowHeights.push({
              row,
              height: Number(ws.getRow(row).height) || Number(ws.properties.defaultRowHeight) || 15
            });
          }
          mergeCellsWithOuterBorder(...mergeBounds);
        }
        const cell = ws.getCell(address);
        cell.value = text || '';
        cell.alignment = {
          ...(cell.alignment || {}),
          horizontal: 'center',
          vertical: 'middle',
          wrapText: true
        };
        // 36行目など先頭行だけを広げると、右側のスタッフ欄との行位置が崩れる。
        // 結合範囲内はテンプレート既定の各行高をそのまま維持する。
        templateRowHeights.forEach(({ row, height }) => {
          ws.getRow(row).height = height;
        });
      };

      // === 担当者総評コメント・輝いていたスタッフの書き込み ===
      if (!isHQStore) {
        const hallComment = getHallSummaryComment(storeAnswers);
        const backyardComment = getBackyardSummaryComment(storeAnswers);
        const staffName = storeAnswers.staffName || '';
        const staffPosition = storeAnswers.staffPosition || '';
        const staffReason = storeAnswers.staffReason || '';

        // テンプレートの見本コメントが入っている実際の記入欄へ編別に出力する。
        setSummaryComment('F36', hallComment, 36, [36, 6, 40, 12]);
        setSummaryComment('E80', backyardComment, 80, [80, 5, 81, 20]);
        if (staffName) ws.getCell('N37').value = staffName;
        if (staffPosition) ws.getCell('Q37').value = staffPosition;
        if (staffReason) ws.getCell('N38').value = staffReason;

        // === 集計表（R84〜R92）の数式セルに直接値を書き込む ===
        // Excelの Protected View（保護されたビュー）では数式が再計算されないため、
        // JavaScript側で計算した値を静的な数値として直接セルに書き込むことで
        // 「編集を有効にする」を押さなくても正しい数字が表示されるようにする

        const hallCats    = appChecklist.filter(c => c.edition === 'hall');
        const strengtheningIds = new Set(['q_special', 'q_special_ai']);
        const backItems = appChecklist.filter(c => c.edition === 'backyard').flatMap(c => c.items).filter(i => !strengtheningIds.has(i.id));
        const fiveSItem = appChecklist.flatMap(c => c.items).find(i => i.id === 'q_special');
        const aiItem = appChecklist.flatMap(c => c.items).find(i => i.id === 'q_special_ai');

        // 各項目の最大点を合算
        const hallMax    = hallCats.flatMap(c => c.items).reduce((s, i) => s + i.points[0], 0);
        const backMax    = backItems.reduce((s, i) => s + i.points[0], 0);
        const fiveSMax   = fiveSItem ? fiveSItem.points[0] : 0;
        const aiMax      = aiItem ? aiItem.points[0] : 0;

        // 実際に入力されたスコアを合算（未入力は0扱い）
        const hallScore = hallCats.flatMap(c => c.items).reduce((s, i) => {
          const a = storeAnswers[i.id];
          return s + (a && a.score !== undefined ? a.score : 0);
        }, 0);
        const backScore = backItems.reduce((s, i) => {
          const a = storeAnswers[i.id];
          return s + (a && a.score !== undefined ? a.score : 0);
        }, 0);
        const fiveSScore = (storeAnswers['q_special'] && storeAnswers['q_special'].score !== undefined)
          ? storeAnswers['q_special'].score : 0;
        const aiScore = (storeAnswers['q_special_ai'] && storeAnswers['q_special_ai'].score !== undefined)
          ? storeAnswers['q_special_ai'].score : 0;

        const backTotalMax   = backMax + fiveSMax + aiMax;
        const backTotalScore = backScore + fiveSScore + aiScore;

        // ホール・バックヤードの合計セル（数式 SUM(N7:N33) 等を値で上書き）
        ws.getCell('N34').value = hallScore;
        ws.getCell('N67').value = backScore;
        ws.getCell('N70').value = fiveSScore;
        ws.getCell('N72').value = aiScore;

        // 集計表 I列（最大得点）
        ws.getCell('I89').value = hallMax;
        ws.getCell('I93').value = backMax;
        ws.getCell('I94').value = fiveSMax;
        ws.getCell('I95').value = aiMax;

        // J列（除外）= 0
        ws.getCell('J89').value = 0;
        ws.getCell('J93').value = 0;
        ws.getCell('J94').value = 0;
        ws.getCell('J95').value = 0;

        // K列（基準点 = 最大得点 - 除外）
        ws.getCell('K89').value = hallMax;
        ws.getCell('K93').value = backMax;
        ws.getCell('K94').value = fiveSMax;
        ws.getCell('K95').value = aiMax;
        ws.getCell('K92').value = backTotalMax;

        // L列（実得点）
        ws.getCell('L89').value = hallScore;
        ws.getCell('L93').value = backScore;
        ws.getCell('L94').value = fiveSScore;
        ws.getCell('L95').value = aiScore;
        ws.getCell('L92').value = backTotalScore;

        // I92列（バックヤード合算得点）
        ws.getCell('I92').value = backTotalMax;
        ws.getCell('J92').value = 0;

        // N列（得点率）※ 0除算防止
        ws.getCell('N89').value = hallMax  > 0 ? hallScore  / hallMax  : 0;
        ws.getCell('N93').value = backMax  > 0 ? backScore  / backMax  : 0;
        ws.getCell('N94').value = fiveSMax > 0 ? fiveSScore / fiveSMax : 0;
        ws.getCell('N95').value = aiMax    > 0 ? aiScore    / aiMax    : 0;
        ws.getCell('N92').value = backTotalMax > 0 ? backTotalScore / backTotalMax : 0;

        // O列（合計点 ＝ 100点満点換算、青マス）
        const hallPoints = hallMax    > 0 ? Math.round(hallScore    / hallMax    * 100) : 0;
        const backPoints = backTotalMax > 0 ? Math.round(backTotalScore / backTotalMax * 100) : 0;
        ws.getCell('O89').value = hallPoints;
        ws.getCell('O92').value = backPoints;
        ws.getCell('O87').value = hallPoints + backPoints; // 総合評価合計点（黄マス）

        // デバッグ用：計算値を記録
        storeMatchCounts.push(`  └${storeName} 集計: ホール${hallScore}/${hallMax}点→${hallPoints}点 | BK${backScore}/${backMax}+5S${fiveSScore}+AI${aiScore}→${backPoints}点`);
      } else {
        // 本部総評は「コメント・メモ欄」の内側（B36:T39）へ中央表示する。
        setSummaryComment('B36', getHQSummaryComment(storeAnswers), 36, [36, 2, 39, 20]);

        // 本部用シート下部の達成率・得点を静的値で反映する。
        const hqItems = appChecklist.filter(c => c.edition === 'hq').flatMap(c => c.items);
        const officeItems = hqItems.slice(0, 8);
        const backyardItems = hqItems.slice(8);
        const sumScores = items => items.reduce((sum, item) => {
          const value = storeAnswers[item.id]?.score;
          return sum + (value !== undefined ? Number(value) : 0);
        }, 0);
        const officeScore = sumScores(officeItems);
        const backyardScore = sumScores(backyardItems);
        const hqScore = officeScore + backyardScore;
        const hqMax = hqItems.length || 13;
        const hqPoints = hqMax > 0 ? Math.round(hqScore / hqMax * 100) : 0;

        ws.getCell('C29').value = officeItems.length ? officeScore / officeItems.length : 0;
        ws.getCell('I29').value = backyardItems.length ? backyardScore / backyardItems.length : 0;
        ws.getCell('R29').value = hqMax ? hqScore / hqMax : 0;
        ['C29', 'I29', 'R29'].forEach(address => { ws.getCell(address).numFmt = '0%'; });
        ws.getCell('A31').value = `${officeScore} / ${officeItems.length}`;
        ws.getCell('G31').value = `${backyardScore} / ${backyardItems.length}`;
        ws.getCell('P31').value = `${hqScore} / ${hqMax}（${hqPoints}点）`;
        storeMatchCounts.push(`  └${storeName} 集計: ${hqScore}/${hqMax}点→${hqPoints}点`);
      }

      // === 結果資料シートへの書き込み（全店分・色付き） ===
      // 店舗用・本部用のどちらのExcelを出力した場合も、結果資料へ同じ集計結果を反映する
      if (kekkaWs && _monthCol) {
        // 結果資料の色を明示指定する。
        // 見本セルのコピーはExcelJSでテーマ色が失われる場合があるため使用しない。
        const applyResultColor = (cell, colorKey) => {
          const colors = {
            red:  { fill: 'FFFF0000', font: 'FFFFFFFF' }, // 1位
            gray: { fill: 'FFD9D9D9', font: 'FF000000' }, // 最下位
            blue: { fill: 'FF9DC3E6', font: 'FF000000' }  // 1位・最下位以外の同率
          };

          // 単独の中間順位は完全に色なし（塗りつぶしなし・黒文字）
          if (!colorKey) {
            cell.fill = {
              type: 'pattern',
              pattern: 'none'
            };
            cell.font = {
              ...(cell.font || {}),
              color: { argb: 'FF000000' },
              bold: false
            };
            return;
          }

          const style = colors[colorKey];
          cell.fill = {
            type: 'pattern',
            pattern: 'solid',
            fgColor: { argb: style.fill },
            bgColor: { argb: style.fill }
          };
          cell.font = {
            ...(cell.font || {}),
            color: { argb: style.font },
            bold: colorKey === 'red'
          };
        };

        // 色見本は履歴を書き込む前のテンプレート原本から複製して保持する。
        // 過去月を手動補正しても見本色そのものが変わらないようにする。
        const resultStyleTemplates = {
          score: {
            red: JSON.parse(JSON.stringify(kekkaWs.getCell('B7').style || {})),
            gray: JSON.parse(JSON.stringify(kekkaWs.getCell('B8').style || {})),
            blue: JSON.parse(JSON.stringify(kekkaWs.getCell('B9').style || {}))
          },
          rank: {
            red: JSON.parse(JSON.stringify(kekkaWs.getCell('B20').style || {})),
            gray: JSON.parse(JSON.stringify(kekkaWs.getCell('B21').style || {})),
            blue: JSON.parse(JSON.stringify(kekkaWs.getCell('B22').style || {}))
          }
        };

        // 店舗別チェック項目分析表の書式ルール
        // ・100%だけ赤（白文字）
        // ・100%未満はすべて塗りつぶしなし（黒文字）
        // B:C、D:E、F:G、H:I が結合セルのため、左右2セルへ明示的に同じ書式を適用する。
        const applyAnalysisRateStyle = (rowNumber, startCol, rate) => {
          const numericRate = Number(rate);
          const isFullScore = Number.isFinite(numericRate) && Math.abs(numericRate - 1) < 1e-9;

          for (let offset = 0; offset < 2; offset++) {
            const cell = kekkaWs.getRow(rowNumber).getCell(startCol + offset);

            // ExcelJSでは同じスタイルIDのセルがstyleオブジェクトを共有する場合がある。
            // fill/fontを直接変更すると別の店舗セルまで同じ色に変わるため、
            // 既存styleを複製してからセル固有のstyleとして置き換える。
            const nextStyle = JSON.parse(JSON.stringify(cell.style || {}));

            if (isFullScore) {
              nextStyle.fill = {
                type: 'pattern',
                pattern: 'solid',
                fgColor: { argb: 'FFFF0000' },
                bgColor: { argb: 'FFFF0000' }
              };
              nextStyle.font = {
                ...(nextStyle.font || {}),
                color: { argb: 'FFFFFFFF' },
                bold: true
              };
            } else {
              nextStyle.fill = {
                type: 'pattern',
                pattern: 'none'
              };
              nextStyle.font = {
                ...(nextStyle.font || {}),
                color: { argb: 'FF000000' },
                bold: false
              };
            }

            cell.style = nextStyle;
          }
        };

        let reflectedScores = 0;
        let reflectedRanks = 0;
        let reflectedAnalysis = 0;
        let reflectedMonths = 0;

        // 4月から選択月までの月別履歴を点数表・順位表へ反映する。
        // これにより9月出力時も8月までの結果がクラウドから復元される。
        const historyEntries = Object.entries(monthlyHistoryMap || {})
          .filter(([, record]) => record && record.scores)
          .sort(([a], [b]) => a.localeCompare(b));

        for (const [yearMonth, record] of historyEntries) {
          const monthCol = _getMonthColFromYearMonth(yearMonth);
          if (!monthCol) continue;
          reflectedMonths++;

          for (const [sName, scoreValue] of Object.entries(record.scores || {})) {
            const scoreRow = _findRow(kekkaWs, 6, 16, sName);
            if (!scoreRow || scoreValue === '' || scoreValue === null || scoreValue === undefined) continue;
            const cell = kekkaWs.getRow(scoreRow).getCell(monthCol);
            cell.value = Number(scoreValue);
            if (sName === '本部' || sName.includes('本部')) {
              applyResultColor(cell, null);
              cell.font = { ...(cell.font || {}), bold: true, color: { argb: 'FF000000' } };
            } else {
              applyResultColor(cell, getResultColorKeyFromRanks(sName, record.ranks));
            }
            reflectedScores++;
          }

          for (const [sName, rankValue] of Object.entries(record.ranks || {})) {
            if (rankValue === '' || rankValue === null || rankValue === undefined) continue;
            const rankRow = _findRow(kekkaWs, 17, 27, sName);
            if (!rankRow) continue;
            const cell = kekkaWs.getRow(rankRow).getCell(monthCol);
            cell.value = Number(rankValue);
            applyResultColor(cell, getResultColorKeyFromRanks(sName, record.ranks));
            reflectedRanks++;
          }
        }

        // 店舗別チェック項目分析表は、選択した審査日の最新詳細データを表示する。
        for (const [sName, sData] of Object.entries(allStoreCache)) {
          if (!sData.isHQ) {
            const analysisRow = _findRow(kekkaWs, 28, 50, sName);
            if (analysisRow) {
              const aRow = kekkaWs.getRow(analysisRow);
              const analysisValues = [
                { col: 2, rate: sData.hallRate },
                { col: 4, rate: sData.backRate },
                { col: 6, rate: sData.fiveSRate },
                { col: 8, rate: sData.aiRate }
              ];

              analysisValues.forEach(({ col, rate }) => {
                aRow.getCell(col).value = rate;
                applyAnalysisRateStyle(analysisRow, col, rate);
              });
              reflectedAnalysis++;
            }
          }
        }

        // 半期平均などテンプレート内の数式をExcel起動時に再計算させる
        workbook.calcProperties = {
          ...(workbook.calcProperties || {}),
          fullCalcOnLoad: true,
          forceFullCalc: true,
          calcMode: 'auto'
        };

        // 最終書式固定：Excel書き出し直前にテンプレートの実セル書式を丸ごと適用する。
        // fill/font の個別設定が無視される環境でも、赤・灰・青を確実に反映させる。
        const scoreRowsFixed = {
          '岩槻本店': 7, '桶川店': 8, '平塚店': 9,
          'ふじみ野店': 10, '美女木店': 11, '鶴瀬店': 12
        };
        const rankRowsFixed = {
          '岩槻本店': 20, '桶川店': 21, '平塚店': 22,
          'ふじみ野店': 23, '美女木店': 24, '鶴瀬店': 25
        };
        const forceTemplateStyle = (dest, styleTemplate) => {
          if (!dest || !styleTemplate) return;
          dest.style = JSON.parse(JSON.stringify(styleTemplate));
        };

        // 履歴として表示した各月へ最終書式を固定する。
        for (const [yearMonth, record] of historyEntries) {
          const monthCol = _getMonthColFromYearMonth(yearMonth);
          if (!monthCol) continue;
          Object.keys(record.ranks || {}).forEach((sName) => {
            const colorKey = getResultColorKeyFromRanks(sName, record.ranks);
            const scoreRow = scoreRowsFixed[sName];
            const rankRow = rankRowsFixed[sName];

            if (scoreRow) {
              const dest = kekkaWs.getRow(scoreRow).getCell(monthCol);
              if (colorKey) forceTemplateStyle(dest, resultStyleTemplates.score[colorKey]);
              else applyResultColor(dest, null);
            }
            if (rankRow) {
              const dest = kekkaWs.getRow(rankRow).getCell(monthCol);
              if (colorKey) forceTemplateStyle(dest, resultStyleTemplates.rank[colorKey]);
              else applyResultColor(dest, null);
            }
          });

          // 本部は順位対象外。点数セルだけ色なしに固定。
          const hqScore = record.scores?.['本部'];
          if (hqScore !== undefined && hqScore !== null && hqScore !== '') {
            const hqRow = _findRow(kekkaWs, 6, 16, '本部');
            if (hqRow) {
              const dest = kekkaWs.getRow(hqRow).getCell(monthCol);
              applyResultColor(dest, null);
              dest.font = { ...(dest.font || {}), bold: true, color: { argb: 'FF000000' } };
            }
          }
        }

        // 点数表・順位表の空白マスは、テンプレートの灰色を残さず完全に色なしにする。
        const clearBlankMonthlyCells = (startRow, endRow) => {
          for (let rowNumber = startRow; rowNumber <= endRow; rowNumber++) {
            for (let colNumber = 2; colNumber <= 13; colNumber++) {
              const cell = kekkaWs.getRow(rowNumber).getCell(colNumber);
              const value = cell.value;
              const isBlank = value === null || value === undefined || value === '';
              if (isBlank) {
                cell.fill = { type: 'pattern', pattern: 'none' };
                cell.font = {
                  ...(cell.font || {}),
                  color: { argb: 'FF000000' },
                  bold: false
                };
              }
            }
          }
        };
        clearBlankMonthlyCells(7, 13);  // 点数表（本部行を含む）
        clearBlankMonthlyCells(20, 25); // 順位表

        storeMatchCounts.push(
          `  └結果資料: ${reflectedMonths}か月分の履歴を反映（点数${reflectedScores}セル・順位${reflectedRanks}セル）／分析${reflectedAnalysis}店舗`
        );
      }

      // === 写真シート ===
      const storePhotos = [];
      for (const qId in storeAnswers) {
        const photos = getAnswerPhotos(storeAnswers[qId]);
        if (photos.length > 0) {
          const itemText = appChecklist.flatMap(c => c.items).find(i => i.id === qId)?.text || qId;
          photos.forEach((base64, photoIndex) => {
            storePhotos.push({
              text: photos.length > 1 ? `${itemText}（${photoIndex + 1}/${photos.length}）` : itemText,
              base64
            });
          });
        }
      }

      if (storePhotos.length > 0) {
        const photoWs = workbook.addWorksheet('写真');
        photoWs.getColumn(1).width = 50;
        photoWs.getColumn(2).width = 60;
        photoWs.addRow(['項目名', '写真']);

        let pRowIndex = 2;
        storePhotos.forEach(p => {
          photoWs.addRow([p.text, '']);
          const base64Data = p.base64.replace(/^data:image\/\w+;base64,/, "");
          const imageId = workbook.addImage({ base64: base64Data, extension: 'jpeg' });
          photoWs.getRow(pRowIndex).height = 200;
          photoWs.addImage(imageId, {
            tl: { col: 1, row: pRowIndex - 1 },
            ext: { width: 300, height: 260 } 
          });
          pRowIndex++;
        });
      }

      // 1店舗分のエクセルデータをバッファ化してZIPに追加
      const buffer = await workbook.xlsx.writeBuffer();
      // 店舗マスタには既に「店」が含まれるため、ファイル名へ追加しない。
      zip.file(`${storeName}_AKT活動審査表.xlsx`, buffer);
    }

    // ZIP生成とダウンロード
    const zipBlob = await zip.generateAsync({ type: "blob" });
    saveAs(zipBlob, `AKT活動審査表_${dateStr}.zip`);
    
    // マッチング結果をユーザーにお知らせする（デバッグ用）
    alert(`出力が完了しました！\n\n【テンプレートへの反映状況】\n${storeMatchCounts.join('\n')}\n\n※0件マッチの場合は項目名違いです。`);
    
  } catch(e) {
    console.error(e);
    alert("Excel出力中にエラーが発生しました。");
  } finally {
    btnElement.textContent = 'Excel形式で一括出力';
    btnElement.disabled = false;
  }
}

// ----- ADMIN LOGIC -----
function verifyPassword() {
  if (adminPasswordInput.value === ADMIN_PASSWORD) {
    passwordModal.classList.add('hidden');
    openAdminPanel();
  } else {
    alert("パスワードが違います");
  }
}

function openAdminPanel() {
  switchScreen('admin');
  switchAdminTab('route');
}

function switchAdminTab(tab) {
  const configActions = btnSaveAdmin?.parentElement;
  tabAdminRoute.classList.toggle('active', tab === 'route');
  tabAdminChecklist.classList.toggle('active', tab === 'checklist');
  if (tabAdminHistory) tabAdminHistory.classList.toggle('active', tab === 'history');

  viewAdminRoute.classList.toggle('hidden', tab !== 'route');
  viewAdminChecklist.classList.toggle('hidden', tab !== 'checklist');
  if (viewAdminHistory) viewAdminHistory.classList.toggle('hidden', tab !== 'history');

  // ルート・採点項目の保存ボタンは月別結果管理では隠し、誤操作を防ぐ。
  if (configActions) configActions.classList.toggle('hidden', tab === 'history');

  if (tab === 'route') {
    renderAdminRoute();
  } else if (tab === 'checklist') {
    renderAdminChecklist();
  } else if (tab === 'history') {
    if (historyMonthSelect && !historyMonthSelect.value) {
      historyMonthSelect.value = getYearMonth(getTodayIsoDate());
    }
    loadHistoryEditor();
  }
}

function renderHistoryEditor(record) {
  if (!historyEditor) return;
  const yearMonth = record?.yearMonth || historyMonthSelect?.value || '';
  const scores = record?.scores || {};
  const ranks = record?.ranks || {};

  const rows = appStores.map(storeName => {
    const isHQ = storeName === '本部' || storeName.includes('本部');
    const score = scores[storeName] ?? '';
    const rank = isHQ ? '' : (ranks[storeName] ?? '');
    const maxScore = isHQ ? 100 : 200;
    return `
      <tr>
        <td style="padding:8px 6px; white-space:nowrap;">${storeName}</td>
        <td style="padding:6px;"><input class="history-score-input" data-store="${storeName}" type="number" min="0" max="${maxScore}" step="1" value="${score}" style="min-width:80px; padding:8px;"></td>
        <td style="padding:6px;">${isHQ
          ? '<span class="text-secondary">―</span>'
          : `<input class="history-rank-input" data-store="${storeName}" type="number" min="1" max="6" step="1" value="${rank}" style="min-width:70px; padding:8px;">`}
        </td>
      </tr>`;
  }).join('');

  historyEditor.innerHTML = `
    <div style="overflow-x:auto; border:1px solid var(--card-border); border-radius:12px;">
      <table style="width:100%; border-collapse:collapse; min-width:360px;">
        <thead>
          <tr style="background:rgba(255,255,255,0.06);">
            <th style="text-align:left; padding:9px 6px;">店舗</th>
            <th style="text-align:left; padding:9px 6px;">点数</th>
            <th style="text-align:left; padding:9px 6px;">順位</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
    <p class="text-secondary text-sm mt-2">※順位は店舗6店のみ。本部は順位対象外です。手動修正を保存すると、自動Excel出力ではその月の手動値を優先します。</p>
  `;

  if (historyStatus) {
    const source = record?.sourceDate
      ? (record.sourceDate === 'baseline' ? '初期登録（4～7月確定値）' : `元審査日: ${record.sourceDate}`)
      : 'クラウド履歴なし（新規）';
    const manual = record?.manualOverride ? '／手動補正済み' : '';
    historyStatus.textContent = `${yearMonth || ''}　${source}${manual}`;
  }
}

async function loadHistoryEditor() {
  if (!historyMonthSelect || !historyEditor) return;
  const yearMonth = historyMonthSelect.value;
  if (!yearMonth) { alert('対象月を選択してください'); return; }

  if (btnLoadHistory) { btnLoadHistory.disabled = true; btnLoadHistory.textContent = '読込中...'; }
  if (historyStatus) historyStatus.textContent = 'クラウドから月別結果を読み込んでいます...';
  try {
    await ensureBaselineHistorySeeded();
    let record = await loadMonthlyHistoryFromCloud(yearMonth);
    if (!record && BASELINE_MONTHLY_RESULTS[yearMonth]) {
      const b = BASELINE_MONTHLY_RESULTS[yearMonth];
      record = normalizeMonthlyHistoryRecord(yearMonth, { ...b, sourceDate: 'baseline', baseline: true });
    }
    if (!record) {
      record = normalizeMonthlyHistoryRecord(yearMonth, {
        sourceDate: '', scores: {}, ranks: {}, manualOverride: false, baseline: false
      });
    }
    loadedHistoryRecord = record;
    renderHistoryEditor(record);
  } catch (err) {
    console.error('[月別結果管理] 読込エラー', err);
    alert('月別結果の読み込みに失敗しました。');
  } finally {
    if (btnLoadHistory) { btnLoadHistory.disabled = false; btnLoadHistory.textContent = 'クラウドから読込'; }
  }
}

function collectHistoryEditorScores() {
  const scores = {};
  document.querySelectorAll('.history-score-input').forEach(input => {
    if (input.value === '') return;
    const n = Number(input.value);
    if (Number.isFinite(n)) scores[input.dataset.store] = n;
  });
  return scores;
}

function collectHistoryEditorRanks() {
  const ranks = {};
  document.querySelectorAll('.history-rank-input').forEach(input => {
    if (input.value === '') return;
    const n = Number(input.value);
    if (Number.isFinite(n)) ranks[input.dataset.store] = n;
  });
  return ranks;
}

function recalcHistoryRanksInEditor() {
  const scores = collectHistoryEditorScores();
  const ranks = calculateRanksFromScores(scores);
  document.querySelectorAll('.history-rank-input').forEach(input => {
    const rank = ranks[input.dataset.store];
    input.value = rank !== undefined ? rank : '';
  });
}

async function saveHistoryEditorToCloud() {
  if (!historyMonthSelect?.value) { alert('対象月を選択してください'); return; }
  const yearMonth = historyMonthSelect.value;
  const scores = collectHistoryEditorScores();
  const ranks = collectHistoryEditorRanks();

  const regularStoresWithScore = Object.keys(scores).filter(name => !(name === '本部' || name.includes('本部')));
  if (regularStoresWithScore.length > 0) {
    for (const name of regularStoresWithScore) {
      const score = Number(scores[name]);
      if (score < 0 || score > 200) { alert(`${name}の点数は0～200で入力してください。`); return; }
      if (!Number.isFinite(Number(ranks[name])) || Number(ranks[name]) < 1 || Number(ranks[name]) > 6) {
        alert(`${name}の順位は1～6で入力してください。`); return;
      }
    }
  }
  if (scores['本部'] !== undefined && (Number(scores['本部']) < 0 || Number(scores['本部']) > 100)) {
    alert('本部の点数は0～100で入力してください。'); return;
  }

  const ok = confirm(`${yearMonth.replace('-', '年')}月の点数・順位を手動補正値としてクラウド保存しますか？\n\n保存後はExcel出力でもこの手動値が優先されます。`);
  if (!ok) return;

  btnSaveHistory.disabled = true;
  btnSaveHistory.textContent = '保存中...';
  try {
    const record = await saveMonthlyHistoryToCloud({
      yearMonth,
      sourceDate: loadedHistoryRecord?.sourceDate || 'manual',
      scores,
      ranks,
      manualOverride: true,
      baseline: false,
      schemaVersion: 1
    }, 'admin-manual');
    loadedHistoryRecord = record;
    renderHistoryEditor(record);
    alert('月別結果の点数・順位をクラウドへ保存しました。\n次回のExcel出力からこの修正値が反映されます。');
  } catch (err) {
    console.error('[月別結果管理] 保存エラー', err);
    alert('月別結果のクラウド保存に失敗しました。');
  } finally {
    btnSaveHistory.disabled = false;
    btnSaveHistory.textContent = '点数・順位をクラウド保存';
  }
}

function reorderArrayByOriginalIndexes(targetArray, originalIndexes) {
  if (!Array.isArray(targetArray) || !Array.isArray(originalIndexes)) return false;
  if (originalIndexes.length !== targetArray.length) return false;
  const uniqueIndexes = new Set(originalIndexes);
  if (uniqueIndexes.size !== targetArray.length || originalIndexes.some(index => index < 0 || index >= targetArray.length)) return false;
  const snapshot = targetArray.slice();
  targetArray.splice(0, targetArray.length, ...originalIndexes.map(index => snapshot[index]));
  return true;
}

function setupDragSort(container, itemSelector, onReorder) {
  if (!container) return;
  const directItems = () => Array.from(container.children).filter(element => element.matches(itemSelector));
  const orderFromDom = () => directItems().map(element => Number(element.dataset.dragIndex));
  const originalOrder = orderFromDom();
  let draggedItem = null;
  let draggedHandle = null;
  let dragGhost = null;
  let active = false;

  const clearInsertMarkers = () => {
    directItems().forEach(element => element.classList.remove('drag-insert-before', 'drag-insert-after'));
  };

  const clearDragState = () => {
    clearInsertMarkers();
    directItems().forEach(element => {
      element.classList.remove('dragging');
      element.style.removeProperty('--drag-placeholder-height');
    });
    if (draggedHandle) draggedHandle.setAttribute('aria-grabbed', 'false');
    if (dragGhost) dragGhost.remove();
    document.body.classList.remove('drag-sort-active');
    draggedItem = null;
    draggedHandle = null;
    dragGhost = null;
    active = false;
  };

  const restoreOriginalOrder = () => {
    const byIndex = new Map(directItems().map(element => [Number(element.dataset.dragIndex), element]));
    originalOrder.forEach(index => {
      const element = byIndex.get(index);
      if (element) container.appendChild(element);
    });
    clearDragState();
  };

  const commitOrder = () => {
    if (!active) return;
    const nextOrder = orderFromDom();
    const changed = nextOrder.some((index, position) => index !== originalOrder[position]);
    clearDragState();
    if (changed) onReorder(nextOrder);
  };

  const moveToPointerPosition = clientY => {
    if (!draggedItem) return;
    const candidates = directItems().filter(element => element !== draggedItem);
    const beforeItem = candidates.find(element => {
      const rect = element.getBoundingClientRect();
      return clientY < rect.top + rect.height / 2;
    });

    clearInsertMarkers();
    if (beforeItem) {
      container.insertBefore(draggedItem, beforeItem);
      beforeItem.classList.add('drag-insert-before');
    } else {
      container.appendChild(draggedItem);
      candidates[candidates.length - 1]?.classList.add('drag-insert-after');
    }
  };

  directItems().forEach(item => {
    const handle = item.querySelector('.drag-handle');
    if (!handle) return;
    handle.draggable = false;
    handle.setAttribute('aria-grabbed', 'false');

    handle.addEventListener('pointerdown', event => {
      if (event.pointerType === 'mouse' && event.button !== 0) return;
      event.preventDefault();
      draggedItem = item;
      draggedHandle = handle;
      active = true;
      const itemRect = item.getBoundingClientRect();
      const pointerOffsetY = event.clientY - itemRect.top;

      dragGhost = item.cloneNode(true);
      dragGhost.classList.remove('dragging', 'drag-insert-before', 'drag-insert-after');
      dragGhost.classList.add('drag-ghost');
      dragGhost.removeAttribute('data-drag-index');
      dragGhost.setAttribute('aria-hidden', 'true');
      dragGhost.querySelectorAll('[id]').forEach(element => element.removeAttribute('id'));
      dragGhost.style.left = `${itemRect.left}px`;
      dragGhost.style.top = `${itemRect.top}px`;
      dragGhost.style.width = `${itemRect.width}px`;
      document.body.appendChild(dragGhost);

      item.classList.add('dragging');
      item.style.setProperty('--drag-placeholder-height', `${Math.min(itemRect.height, 64)}px`);
      handle.setAttribute('aria-grabbed', 'true');
      document.body.classList.add('drag-sort-active');
      try { handle.setPointerCapture(event.pointerId); } catch (_) {}

      const handlePointerMove = moveEvent => {
        if (!active || !draggedItem) return;
        moveEvent.preventDefault();
        if (moveEvent.clientY < 80) window.scrollBy(0, -14);
        if (moveEvent.clientY > window.innerHeight - 80) window.scrollBy(0, 14);
        if (dragGhost) dragGhost.style.top = `${moveEvent.clientY - Math.min(pointerOffsetY, 42)}px`;
        moveToPointerPosition(moveEvent.clientY);
      };
      const finishPointerDrag = endEvent => {
        if (endEvent.type === 'pointercancel') restoreOriginalOrder();
        else commitOrder();
        try { handle.releasePointerCapture(event.pointerId); } catch (_) {}
        document.removeEventListener('pointermove', handlePointerMove);
        document.removeEventListener('pointerup', finishPointerDrag);
        document.removeEventListener('pointercancel', finishPointerDrag);
      };
      document.addEventListener('pointermove', handlePointerMove, { passive: false });
      document.addEventListener('pointerup', finishPointerDrag);
      document.addEventListener('pointercancel', finishPointerDrag);
    });
  });
}

function renderAdminRoute() {
  adminInspectionBaseMonth.value = inspectionCountSettings.baseYearMonth;
  adminInspectionBaseCount.value = inspectionCountSettings.baseCount;
  adminRouteList.innerHTML = '';
  appStores.forEach((store, idx) => {
    const li = document.createElement('li');
    li.className = 'route-draggable drag-sort-item';
    li.dataset.dragIndex = idx;
    li.innerHTML = `
      <div class="draggable-main">
        <button type="button" class="drag-handle" aria-label="${store}をドラッグして並べ替え" title="ドラッグして並べ替え">⠿</button>
        <span>${store}</span>
      </div>
      <div class="actions">
        <button class="btn btn-secondary btn-small" onclick="moveStore(${idx}, -1)">↑</button>
        <button class="btn btn-secondary btn-small" onclick="moveStore(${idx}, 1)">↓</button>
        <button class="btn btn-danger btn-small" onclick="deleteStore(${idx})">🗑️</button>
      </div>
    `;
    adminRouteList.appendChild(li);
  });
  setupDragSort(adminRouteList, '.route-draggable', order => {
    if (reorderArrayByOriginalIndexes(appStores, order)) renderAdminRoute();
  });
}

function adminAddStore() {
  const name = newStoreInput.value.trim();
  if (name) {
    appStores.push(name);
    newStoreInput.value = '';
    renderAdminRoute();
  }
}

window.moveStore = (idx, dir) => {
  if (idx + dir >= 0 && idx + dir < appStores.length) {
    const temp = appStores[idx];
    appStores[idx] = appStores[idx + dir];
    appStores[idx + dir] = temp;
    renderAdminRoute();
  }
};

window.deleteStore = (idx) => {
  if (confirm(`${appStores[idx]} を削除しますか？`)) {
    appStores.splice(idx, 1);
    renderAdminRoute();
  }
};

function renderAdminChecklist() {
  adminCategoriesContainer.innerHTML = '';
  appChecklist.forEach((cat, cIdx) => {
    const catCard = document.createElement('div');
    catCard.className = 'admin-category-card drag-sort-item';
    catCard.dataset.dragIndex = cIdx;
    const isCollapsed = collapsedAdminCategories.has(cat);
    if (isCollapsed) catCard.classList.add('collapsed');
    
    const cHeader = document.createElement('div');
    cHeader.className = 'admin-category-header';
    
    const editionSelectHTML = `
      <select onchange="updateCatEdition(${cIdx}, this.value)" style="width: auto; padding: 4px;">
        <option value="both" ${cat.edition === 'both' ? 'selected' : ''}>共通</option>
        <option value="hall" ${cat.edition === 'hall' ? 'selected' : ''}>ホール編</option>
        <option value="backyard" ${cat.edition === 'backyard' ? 'selected' : ''}>バックヤード編</option>
        <option value="hq" ${cat.edition === 'hq' ? 'selected' : ''}>本部編</option>
      </select>
    `;

    cHeader.innerHTML = `
      <div class="admin-category-fields">
        <button type="button" class="drag-handle" aria-label="${cat.category}カテゴリーをドラッグして並べ替え" title="カテゴリーをドラッグして並べ替え">⠿</button>
        <input type="text" value="${cat.category}" onchange="updateCatName(${cIdx}, this.value)" style="font-weight:bold; flex:1;">
        ${editionSelectHTML}
      </div>
      <div class="admin-category-actions">
        <button type="button" class="btn btn-secondary btn-small" onclick="toggleAdminCategory(${cIdx})">${isCollapsed ? '設問を開く' : '設問を閉じる'}</button>
        <button class="btn btn-danger btn-small" onclick="deleteCategory(${cIdx})">カテゴリ削除</button>
      </div>
    `;
    catCard.appendChild(cHeader);

    const itemsContainer = document.createElement('div');
    itemsContainer.className = 'admin-items-container';
    cat.items.forEach((item, iIdx) => {
      const row = document.createElement('div');
      row.className = 'admin-item-row drag-sort-item';
      row.dataset.dragIndex = iIdx;
      const ptsStr = item.points.join(',');
      const isPri = item.isPriority ? 'checked' : '';
      
      row.innerHTML = `
        <div class="admin-item-heading">
          <button type="button" class="drag-handle" aria-label="設問${iIdx + 1}をドラッグして並べ替え" title="設問をドラッグして並べ替え">⠿</button>
          <input type="text" value="${item.text}" onchange="updateItemText(${cIdx}, ${iIdx}, this.value)" style="flex:1;">
          <button class="btn btn-danger btn-small" onclick="deleteItem(${cIdx}, ${iIdx})">🗑️</button>
        </div>
        <div style="display:flex; gap:16px; align-items:center;">
          <input type="text" value="${ptsStr}" onchange="updateItemPoints(${cIdx}, ${iIdx}, this.value)" placeholder="配点(例:5,1,0)" style="width:120px;">
          <label class="toggle-label">
            <input type="checkbox" ${isPri} onchange="updateItemPriority(${cIdx}, ${iIdx}, this.checked)">
            強化項目にする
          </label>
        </div>
      `;
      itemsContainer.appendChild(row);
    });
    if (!isCollapsed) {
      setupDragSort(itemsContainer, '.admin-item-row', order => {
        if (reorderArrayByOriginalIndexes(appChecklist[cIdx].items, order)) renderAdminChecklist();
      });
      catCard.appendChild(itemsContainer);

      const btnAddItem = document.createElement('button');
      btnAddItem.className = 'btn btn-secondary btn-small';
      btnAddItem.textContent = '+ 設問を追加';
      btnAddItem.onclick = () => addItem(cIdx);
      catCard.appendChild(btnAddItem);
    }

    adminCategoriesContainer.appendChild(catCard);
  });
  setupDragSort(adminCategoriesContainer, '.admin-category-card', order => {
    if (reorderArrayByOriginalIndexes(appChecklist, order)) renderAdminChecklist();
  });
}

window.toggleAdminCategory = cIdx => {
  const category = appChecklist[cIdx];
  if (!category) return;
  if (collapsedAdminCategories.has(category)) collapsedAdminCategories.delete(category);
  else collapsedAdminCategories.add(category);
  renderAdminChecklist();
};
window.collapseAllAdminCategories = () => {
  appChecklist.forEach(category => collapsedAdminCategories.add(category));
  renderAdminChecklist();
};
window.expandAllAdminCategories = () => {
  appChecklist.forEach(category => collapsedAdminCategories.delete(category));
  renderAdminChecklist();
};

window.updateCatName = (cIdx, val) => { appChecklist[cIdx].category = val; };
window.updateCatEdition = (cIdx, val) => { appChecklist[cIdx].edition = val; };
window.deleteCategory = (cIdx) => { if(confirm('カテゴリを削除しますか？')) { appChecklist.splice(cIdx, 1); renderAdminChecklist(); } };

window.updateItemText = (cIdx, iIdx, val) => { appChecklist[cIdx].items[iIdx].text = val; };
window.updateItemPoints = (cIdx, iIdx, val) => { 
  const arr = val.split(',').map(n => parseInt(n.trim())).filter(n => !isNaN(n));
  if (arr.length > 0) appChecklist[cIdx].items[iIdx].points = arr; 
};
window.updateItemPriority = (cIdx, iIdx, checked) => { appChecklist[cIdx].items[iIdx].isPriority = checked; };
window.deleteItem = (cIdx, iIdx) => { if(confirm('設問を削除しますか？')) { appChecklist[cIdx].items.splice(iIdx, 1); renderAdminChecklist(); } };
window.addItem = (cIdx) => {
  appChecklist[cIdx].items.push({ id: `q_${Date.now()}`, text: '新しい設問', points: [3,1,0], isPriority: false });
  renderAdminChecklist();
};
function adminAddCategory() {
  appChecklist.push({ category: '新しいカテゴリ', items: [] });
  renderAdminChecklist();
}

async function saveAdminData() {
  const baseYearMonth = adminInspectionBaseMonth.value;
  const baseCount = Number(adminInspectionBaseCount.value);
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(baseYearMonth) || !Number.isInteger(baseCount) || baseCount < 1) {
    alert('審査回数の基準年月と基準回数を正しく入力してください。');
    adminInspectionBaseMonth.focus();
    return;
  }
  inspectionCountSettings = normalizeInspectionCountSettings({ baseYearMonth, baseCount });

  // まず端末へ保存。通信不良でもこの端末では設定を失わない。
  saveDataToLocal();

  btnSaveAdmin.disabled = true;
  const originalText = btnSaveAdmin.textContent;
  btnSaveAdmin.textContent = 'クラウドへ保存中...';

  let cloudSaved = false;
  try {
    await saveAdminSettingsToCloud();
    cloudSaved = true;
  } catch (err) {
    console.error('[管理者設定] クラウド保存エラー', err);
  } finally {
    btnSaveAdmin.disabled = false;
    btnSaveAdmin.textContent = originalText || '設定を保存';
  }

  if (cloudSaved) {
    alert("設定を保存しました！\n巡回ルート・採点項目・審査回数設定をクラウドへ同期しました。\n他の端末は次回アプリを開いたときに自動反映されます。");
  } else {
    alert("この端末には設定を保存しましたが、クラウド同期に失敗しました。\nインターネット接続を確認して、もう一度『設定を保存』してください。");
  }

  renderRoutePreview();
  if (state.reviewStatus === 'in_progress') {
    loadStoreScoring();
    switchScreen('scoring');
  } else {
    switchScreen('setup');
  }
}

function resetAdminData() {
  if(confirm('設定を完全にリセットし、初期データ（data.jsの内容）に戻しますか？')) {
    localStorage.removeItem('akt_stores_v2');
    localStorage.removeItem('akt_checklist_v2');
    localStorage.removeItem(INSPECTION_COUNT_SETTINGS_KEY);
    loadData();
    alert('初期データにリセットしました。');
    renderAdminRoute();
    renderAdminChecklist();
  }
}

// Start
init();
